<?php
namespace App\Domain\Content\Services; use App\Domain\Catalog\Models\Product; use App\Domain\Catalog\Models\Collection; use App\Domain\Content\Models\ContentPage;
class SeoService {public function product(Product $p):array{$p->loadMissing(['variants.inventory']);$prices=$p->variants->map(fn($v)=>$v->price_override??$p->base_price);$available=$p->variants->contains(fn($v)=>$v->inventory&&($v->inventory->quantity_on_hand-$v->inventory->quantity_reserved)>0);return $this->meta($p->seo_title?:$p->name.' — RAOZA',$p->seo_description?:$this->excerpt($p->description),$p->canonical_url?:route('products.show',$p),$p->og_image,$p->indexable,['@context'=>'https://schema.org','@type'=>'Product','name'=>$p->name,'description'=>$this->excerpt($p->description),'url'=>route('products.show',$p),'offers'=>['@type'=>'Offer','priceCurrency'=>'EUR','price'=>number_format(($prices->min()??$p->base_price)/100,2,'.',''),'availability'=>$available?'https://schema.org/InStock':'https://schema.org/OutOfStock']]);}
 public function collection(Collection $c):array{return $this->meta($c->seo_title?:$c->name.' — RAOZA',$c->seo_description?:$this->excerpt($c->description),$c->canonical_url?:route('collections.show',$c),$c->og_image,$c->indexable);}
 public function page(ContentPage $x):array{return $this->meta($x->seo_title?:$x->title.' — RAOZA',$x->seo_description?:null,$x->canonical_url?:route('content.show',$x->slug),$x->og_image,$x->indexable);}
 public function basic(string $title,?string $description,string $canonical,bool $indexable=true):array{return $this->meta($title,$description,$canonical,null,$indexable);}
 private function meta(string $title,?string $description,string $canonical,?string $og,bool $indexable,array $jsonLd=[]):array{return compact('title','description','canonical','og','indexable','jsonLd');}
 private function excerpt(?string $v):?string{return $v?mb_substr(trim(strip_tags($v)),0,160):null;}}
